export const TELEMETRY_EVENT_ALIAS_TO_CANONICAL = Object.fromEntries(TELEMETRY_EVENT_ALIAS_TO_CANONICAL_ENTRIES) as Record<string, string>;

const TELEMETRY_CANONICAL_EVENT_NAME_SET = new Set<string>(TELEMETRY_CANONICAL_EVENT_NAMES);

export function resolveTelemetryEventNameForRuntime(eventName: string) {
  const trimmed = eventName.trim();
  if (TELEMETRY_CANONICAL_EVENT_NAME_SET.has(trimmed)) return trimmed;
  return TELEMETRY_EVENT_ALIAS_TO_CANONICAL[trimmed] ?? null;
}

export function isSupportedTelemetryEventNameForRuntime(eventName: string) {
  return resolveTelemetryEventNameForRuntime(eventName) !== null;
}
